"use strict";

// A class DECLARATION inside a top-level `if`, isolated so that the only
// route to the sink in this module is through the conditional branch.
//
// The flag is a runtime value; nothing in the source proves the branch is
// not taken. Reachability asks whether there EXISTS a load on which the
// key runs, and there does. RWF-019's cutoff asks the opposite question --
// whether a call ALWAYS runs and always throws -- and the two must not
// borrow each other's predicates. Answering NOT_AFFECTED here would be
// must-execute reasoning wearing a reachability label.
const danger = require("./danger");

function key() {
  danger.explode("conditional-class-key");
  return "x";
}

if (process.env.FIXTURE_LIB_FLAG === "on") {
  class Conditionally {
    [key()]() {}
  }
  module.exports = Conditionally;
}
